import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import './FarmList.css';

const FarmList = () => {
  const [farms, setFarms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchFarms = async () => {
      try {
        // In a real app, you would connect to your Django API
        // For now, using mock data for demonstration

        // Mock data for demonstration
        const mockFarms = [
          { id: 1, name: 'Green Valley Farm', location: 'California', size: '200 acres' },
          { id: 2, name: 'Sunshine Fields', location: 'Texas', size: '350 acres' },
          { id: 3, name: 'Mountain Ranch', location: 'Colorado', size: '150 acres' },
          { id: 4, name: 'River Bend Farm', location: 'Florida', size: '275 acres' }
        ];

        setFarms(mockFarms);
        setLoading(false);
      } catch (err) {
        setError('Failed to fetch farms');
        setLoading(false);
      }
    };

    fetchFarms();
  }, []);

  if (loading) return <div className="farm-list-loading">Loading farms...</div>;
  if (error) return <div className="farm-list-error">{error}</div>;

  return (
    <div className="farm-list">
      <h2>Farm List</h2>
      <Link to="/farms/new" className="btn btn-primary">Add New Farm</Link>

      <table className="farm-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Location</th>
            <th>Size</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {farms.map(farm => (
            <tr key={farm.id}>
              <td>{farm.name}</td>
              <td>{farm.location}</td>
              <td>{farm.size}</td>
              <td>
                <Link to={`/farms/${farm.id}/edit`} className="btn btn-secondary">Edit</Link>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default FarmList;
